/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/** The two status groups the filter vocabulary accepts alongside concrete statuses. */
export type IssueStatusGroup = "open" | "closed";

const STATUS_GROUP_NAMES: readonly IssueStatusGroup[] = ["open", "closed"];

export const STATUS_GROUPS: Readonly<Record<IssueStatusGroup, readonly IssueStatus[]>> = {
  open: ISSUE_STATUSES.filter(
    (status) => !CLOSED_ISSUE_STATUSES.includes(status),
  ),
  closed: CLOSED_ISSUE_STATUSES,
};

/** Whether `value` is a concrete status or one of the `open`/`closed` groups. */
export function isIssueStatusToken(
  value: string,
): value is IssueStatus | IssueStatusGroup {
  return (
    ISSUE_STATUSES.includes(value as IssueStatus) ||
    STATUS_GROUP_NAMES.includes(value as IssueStatusGroup)
  );
}

/**
 * Expands `open`/`closed` group tokens to their member statuses wherever the
 * vocabulary is read, so `status=open` means the same thing everywhere.
 * Unknown tokens are dropped; the result is deduplicated.
 */
export function expandStatusTokens(
  values: readonly string[],
): readonly IssueStatus[] {
  const expanded = new Set<IssueStatus>();
  for (const value of values) {
    if (STATUS_GROUP_NAMES.includes(value as IssueStatusGroup)) {
      for (const status of STATUS_GROUPS[value as IssueStatusGroup]) {
        expanded.add(status);
      }
    } else if (ISSUE_STATUSES.includes(value as IssueStatus)) {
      expanded.add(value as IssueStatus);
    }
  }
  return [...expanded];
}

